// Image HEADS -> actual original HeadLinker neighbor seed selection. No native input.
import org.audiveris.omr.sheet.Book;
import java.util.*;import java.nio.file.*;import java.awt.geom.*;
public class StemImageSeedsProbe extends StemPartsLookupProbe {
 private final Object book; public StemImageSeedsProbe(Book b,SortedSet<Integer> ids){super(b,ids);book=b;}
 static Object typed(String cls,String name,Class<?>[] types,Object...args)throws Exception {java.lang.reflect.Method m=Class.forName("org.audiveris.omr."+cls).getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(null,args);}
 static String point(Point2D p){return "["+p.getX()+","+p.getY()+"]";}
 public void process(){try{
 Object sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet"); List<String> systems=new ArrayList<>();int corners=0,selectedCount=0; List<String> boundaries=new ArrayList<>(),barBoundaries=new ArrayList<>();
 for(Object sys:(List<?>)call(sheet,"getSystems")){
 Object retr=Class.forName("org.audiveris.omr.sheet.stem.StemsRetriever").getConstructor(Class.forName("org.audiveris.omr.sheet.SystemInfo")).newInstance(sys);call(retr,"process");Object params=get(retr,"params");List<String> cases=new ArrayList<>(),areas=new ArrayList<>(),systemSeeds=new ArrayList<>();
 for(Object area:(List<?>)get(retr,"noStemAreas")){Rectangle2D b=((Area)area).getBounds2D();areas.add("["+b.getX()+","+b.getY()+","+b.getWidth()+","+b.getHeight()+"]");}for(Object seed:(List<?>)get(retr,"systemSeeds"))systemSeeds.add(physical(seed));Collections.sort(systemSeeds);
 for(Object head:(List<?>)get(retr,"systemHeads")){Object hl=call(head,"getLinker");if(hl==null)continue;
 for(String side:new String[]{"LEFT","RIGHT"})for(String vert:new String[]{"TOP","BOTTOM"}){Object c=call(hl,"getCornerLinker",en("util.HorizontalSide",side),en("util.VerticalSide",vert));Point2D ref=(Point2D)get(c,"refPt");int xDir=(Integer)get(get(c,"this$1"),"xDir");List<?> neighbor=new ArrayList<>((Collection<?>)get(hl,"neighborSeeds"));Area seedArea=(Area)call(c,"getSeedArea");List<Object> candidates=new ArrayList<>((Collection<?>)typed("glyph.Glyphs","intersectedGlyphs",new Class<?>[]{Collection.class,Area.class},neighbor,seedArea));
 candidates.sort((a,b)->{try{return Double.compare(((Line2D)call(a,"getCenterLine")).ptSegDistSq(ref),((Line2D)call(b,"getCenterLine")).ptSegDistSq(ref));}catch(Exception e){throw new RuntimeException(e);}});
 if(boundaries.isEmpty()&&!candidates.isEmpty()) {Object g=candidates.get(0);Line2D line=(Line2D)call(g,"getCenterLine");double x=(Double)typed("math.LineUtil","xAtY",new Class<?>[]{Line2D.class,double.class},line,ref.getY());Object oldRef=get(c,"refPt");try{for(double delta:new double[]{Math.nextDown(x-xDir*(-4.5)),x-xDir*(-4.5),Math.nextUp(x-xDir*(-4.5)),Math.nextDown(x-xDir*3.5),x-xDir*3.5,Math.nextUp(x-xDir*3.5)}){Point2D q=new Point2D.Double(delta,ref.getY());set(c,"refPt",q);int gap=(int)Math.round(xDir*(x-q.getX()));boolean eligible=(gap>=0&&gap<=(Integer)get(params,"maxHeadOutDx"))||(gap<=0&&-gap<=(Integer)get(params,"maxHeadInDx"));boundaries.add("{\"glyph\":"+physical(g)+",\"reference\":"+point(q)+",\"x_direction\":"+xDir+",\"y_direction\":"+get(c,"yDir")+",\"gap\":"+gap+",\"eligible\":"+eligible+",\"stands_out\":"+call(c,"standsOut",g)+"}");}java.awt.Rectangle box=(java.awt.Rectangle)call(g,"getBounds");int yd=(Integer)get(c,"yDir");double edgeY=yd<0?box.y+(Integer)get(params,"minHeadStumpDy")-.5:box.y+box.height-1-(Integer)get(params,"minHeadStumpDy")+.5;for(double y:new double[]{Math.nextDown(edgeY),edgeY,Math.nextUp(edgeY)}){Point2D q=new Point2D.Double(ref.getX(),y);set(c,"refPt",q);double xx=(Double)typed("math.LineUtil","xAtY",new Class<?>[]{Line2D.class,double.class},line,y);int gap=(int)Math.round(xDir*(xx-q.getX()));boolean eligible=(gap>=0&&gap<=(Integer)get(params,"maxHeadOutDx"))||(gap<=0&&-gap<=(Integer)get(params,"maxHeadInDx"));boundaries.add("{\"glyph\":"+physical(g)+",\"reference\":"+point(q)+",\"x_direction\":"+xDir+",\"y_direction\":"+yd+",\"gap\":"+gap+",\"eligible\":"+eligible+",\"stands_out\":"+call(c,"standsOut",g)+"}");}}finally{set(c,"refPt",oldRef);}}
 Object chosen=null;List<String> rows=new ArrayList<>(),neighbors=new ArrayList<>();for(Object g:neighbor)neighbors.add(physical(g));Collections.sort(neighbors);
 for(Object g:candidates){Line2D line=(Line2D)call(g,"getCenterLine");double x=(Double)typed("math.LineUtil","xAtY",new Class<?>[]{Line2D.class,double.class},line,ref.getY());int gap=(int)Math.round(xDir*(x-ref.getX()));boolean out=(Boolean)call(c,"standsOut",g);boolean eligible=(gap>=0&&gap<=(Integer)get(params,"maxHeadOutDx"))||(gap<=0&&-gap<=(Integer)get(params,"maxHeadInDx"));if(chosen==null&&eligible&&out)chosen=g;
 rows.add("{\"glyph\":"+physical(g)+",\"gap\":"+gap+",\"stands_out\":"+out+",\"eligible\":"+eligible+"}");}
 if(chosen!=null){selectedCount++;Object stump=call(c,"getStump");if(stump==null||!physical(stump).equals(physical(chosen)))throw new IllegalStateException("seed branch differs from actual original stump");}
 corners++;cases.add("{\"head_bounds\":"+rect(call(head,"getBounds"))+",\"shape\":\""+call(head,"getShape")+"\",\"side\":\""+side+"\",\"vertical\":\""+vert+"\",\"reference\":"+point(ref)+",\"neighbors\":["+String.join(",",neighbors)+"],\"candidates\":["+String.join(",",rows)+"],\"selected_seed\":"+(chosen==null?"null":physical(chosen))+",\"actual_stump\":"+(call(c,"getStump")==null?"null":physical(call(c,"getStump")))+"}");
 }}
 if(barBoundaries.isEmpty()&&!((List<?>)get(retr,"noStemAreas")).isEmpty()){Area area=(Area)((List<?>)get(retr,"noStemAreas")).get(0);Rectangle2D b=area.getBounds2D();Object g=glyph((int)b.getX(),(int)b.getY()+10,(int)b.getWidth()*4,10,"VERTICAL");double old=(Double)get(params,"maxBarOverlap");try{for(double limit:new double[]{Math.nextDown(.25),.25,Math.nextUp(.25)}){set(params,"maxBarOverlap",limit);List<Object> copy=new ArrayList<>(List.of(g));call(retr,"purgeNoStemSeeds",copy);barBoundaries.add("{\"glyph\":"+physical(g)+",\"limit\":"+limit+",\"removed\":"+copy.isEmpty()+"}");}}finally{set(params,"maxBarOverlap",old);}}
 systems.add("{\"no_stem_areas\":["+String.join(",",areas)+"],\"surviving_seeds\":["+String.join(",",systemSeeds)+"],\"system\":"+call(sys,"getId")+",\"max_head_in_dx\":"+get(params,"maxHeadInDx")+",\"max_head_out_dx\":"+get(params,"maxHeadOutDx")+",\"max_head_seed_dy\":"+get(params,"maxHeadSeedDy")+",\"min_head_stump_dy\":"+get(params,"minHeadStumpDy")+",\"cases\":["+String.join(",",cases)+"]}");
 }
 Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"seed_boundaries\":["+String.join(",",boundaries)+"],\"bar_overlap_boundaries\":["+String.join(",",barBoundaries)+"],\"unordered_neighbor_and_seed_catalogs_canonicalized\":true,\"candidate_selection_order_preserved\":true,\"native_outputs_used\":false,\"corners\":"+corners+",\"selected_seed_corners\":"+selectedCount+",\"systems\":["+String.join(",",systems)+"]}");
 }catch(Exception e){throw new RuntimeException(e);}}
}
